#!/usr/bin/env bash
set -euo pipefail

is_precommit_pre_push_shim() {
  local actual expected
  actual=$(sed -E \
    -e 's/^# ID: [[:xdigit:]]{32}$/# ID: <id>/' \
    -e 's|^INSTALL_PYTHON=.*$|INSTALL_PYTHON=<python>|' "$1") || return 1
  expected=$(cat <<'EOF'
#!/usr/bin/env bash
# File generated by pre-commit: https://pre-commit.com
# ID: <id>

# start templated
INSTALL_PYTHON=<python>
ARGS=(hook-impl --config=.pre-commit-config.yaml --hook-type=pre-push)
# end templated

HERE="$(cd "$(dirname "$0")" && pwd)"
ARGS+=(--hook-dir "$HERE" -- "$@")

if [ -x "$INSTALL_PYTHON" ]; then
    exec "$INSTALL_PYTHON" -mpre_commit "${ARGS[@]}"
elif command -v pre-commit > /dev/null; then
    exec pre-commit "${ARGS[@]}"
else
    echo '`pre-commit` not found.  Did you forget to activate your virtualenv?' 1>&2
    exit 1
fi
EOF
  )
  [[ $actual == "$expected" ]]
}

install_hook() {
  local hook_path script_path precommit_path tmp_path
  script_path=${BASH_SOURCE[0]}
  hook_path=$(git rev-parse --git-path hooks/pre-push)
  [[ $hook_path == /* ]] || hook_path="$PWD/$hook_path"
  precommit_path="$hook_path.pre-commit"

  if [[ -L $hook_path ]]; then
    printf 'Refusing to replace symlinked pre-push hook: %s\n' "$hook_path" >&2
    return 1
  fi
  if [[ -L $precommit_path ]]; then
    printf 'Refusing to replace symlinked saved pre-commit hook: %s\n' "$precommit_path" >&2
    return 1
  fi
  if [[ -e $precommit_path ]] && ! is_precommit_pre_push_shim "$precommit_path"; then
    printf 'Refusing to replace unknown saved pre-push hook: %s\n' "$precommit_path" >&2
    return 1
  fi
  if [[ -e $hook_path && -e $precommit_path ]] &&
    ! cmp -s "$hook_path" "$script_path" && ! cmp -s "$hook_path" "$precommit_path"; then
    printf 'Refusing to replace a pre-push hook that differs from its saved copy: %s\n' "$hook_path" >&2
    return 1
  fi
  if [[ -e $hook_path ]]; then
    if cmp -s "$script_path" "$hook_path"; then
      chmod +x "$hook_path"
      return 0
    fi
    if ! is_precommit_pre_push_shim "$hook_path"; then
      printf 'Refusing to replace unknown pre-push hook: %s\n' "$hook_path" >&2
      return 1
    fi
  fi

  mkdir -p "$(dirname "$hook_path")"
  if [[ -e $hook_path && ! -e $precommit_path ]]; then
    cp "$hook_path" "$precommit_path"
    chmod +x "$precommit_path"
  fi
  tmp_path=$(mktemp "$hook_path.tmp.XXXXXX")
  if ! cp "$script_path" "$tmp_path" || ! chmod +x "$tmp_path" || ! mv -f "$tmp_path" "$hook_path"; then
    rm -f "$tmp_path"
    return 1
  fi
}

if [[ ${1:-} == --install ]]; then
  if [[ $# -ne 1 ]]; then
    printf 'Usage: %s --install\n' "$0" >&2
    exit 2
  fi
  install_hook
  exit
fi

precommit_path="${BASH_SOURCE[0]}.pre-commit"
push_input=
if [[ ( -e $precommit_path || -L $precommit_path ) && ! -x $precommit_path ]]; then
  printf 'Saved pre-commit hook is not executable; refusing push: %s\n' "$precommit_path" >&2
  exit 1
fi
if [[ -x $precommit_path ]]; then
  # Keep the bytes for the pre-commit shim after this guard reads them.
  push_input=$(cat; printf '\034')
  push_input=${push_input%$'\034'}
  exec 3<<< "$push_input"
else
  exec 3<&0
fi

run_precommit_hook() {
  if [[ -x $precommit_path ]]; then
    exec 3<&-
    printf '%s' "$push_input" | "$precommit_path" "$@"
    exit $?
  fi
  exit 0
}

if [[ $# -lt 1 ]]; then
  printf 'Cannot identify the push remote; refusing push.\n' >&2
  exit 1
fi
[[ $1 == origin ]] || run_precommit_hook "$@"

branch_updates=
branch_count=0
while IFS= read -r update <&3 || [[ -n $update ]]; do
  [[ -n $update ]] || continue
  local_ref=
  local_sha=
  remote_ref=
  remote_sha=
  extra=
  read -r local_ref local_sha remote_ref remote_sha extra <<< "$update"
  if [[ -z $local_ref || -z $local_sha || -z $remote_ref || -z $remote_sha || -n $extra ]]; then
    printf 'Cannot parse pre-push update; refusing push.\n' >&2
    exit 1
  fi
  [[ $remote_ref == refs/heads/* ]] || continue
  if [[ $local_sha =~ ^0+$ ]]; then
    if [[ $remote_ref == refs/heads/main ]]; then
      printf 'Push blocked: refusing to delete refs/heads/main.\n' >&2
      exit 1
    fi
    continue
  fi
  if [[ ! $local_sha =~ ^[[:xdigit:]]+$ || ! $remote_sha =~ ^[[:xdigit:]]+$ ]]; then
    printf 'Cannot verify pre-push update for %s; refusing push.\n' "$remote_ref" >&2
    exit 1
  fi
  branch_updates+="$remote_ref"$'\t'"$local_sha"$'\n'
  branch_count=$((branch_count + 1))
done

[[ $branch_count -gt 0 ]] || run_precommit_hook "$@"
git fetch --quiet origin +refs/heads/main:refs/remotes/origin/main

failed=0
while IFS=$'\t' read -r remote_ref pushed_sha; do
  [[ -n $remote_ref ]] || continue
  if ! git cat-file -e "${pushed_sha}^{commit}" 2>/dev/null; then
    printf 'Cannot verify pushed commit for %s; refusing push.\n' "$remote_ref" >&2
    failed=1
    continue
  fi
  if ! git merge-base --is-ancestor refs/remotes/origin/main "$pushed_sha"; then
    printf 'Push blocked: %s does not contain the latest origin/main (%s). Merge or rebase origin/main, then retry.\n' \
      "${remote_ref#refs/heads/}" "$(git rev-parse --short refs/remotes/origin/main)" >&2
    failed=1
  fi
done <<< "$branch_updates"

[[ $failed -eq 0 ]] || exit "$failed"
run_precommit_hook "$@"
